<?php

declare(strict_types=1);

namespace App\Repository;

use App\Entity\CashJournal;
use Doctrine\ORM\EntityRepository;
use Doctrine\ORM\Tools\Pagination\Paginator;

/**
 * CashJournalRepository.
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 *
 * @extends EntityRepository<\App\Entity\CashJournalEntry>
 */
class CashJournalEntryRepository extends EntityRepository
{
    public function findAll(): array
    {
        return $this->findBy([], ['date' => 'ASC']);
    }

    /**
     * @param string $search Search term matched against the remark within this journal
     * @param int|string $page Integer page number, including query-string values
     * @param int $limit
     *
     * @return Paginator<\App\Entity\CashJournalEntry>
     */
    public function findByFilter(CashJournal $journal, $search, $page = 1, $limit = 20)
    {
        $q = $this
            ->createQueryBuilder('cje')
            ->select('cje')
            ->where('cje.cashJournal = :journal and cje.remark LIKE :search')
            ->setParameter('search', '%'.$search.'%')
            ->setParameter('journal', $journal)
            ->addOrderBy('cje.date', \SortDirection::Ascending)
            ->setFirstResult(($page - 1) * $limit)
            ->setMaxResults($limit)
            ->getQuery();
        $paginator = new Paginator($q, $fetchJoinCollection = false);

        return $paginator;
    }

    /**
     * @param CashJournal $journal Supplies the year; entries from all journals in that year are considered
     *
     * @return int|string|null Raw maximum document number, or null when no entries match
     */
    public function getLastDocumentNumber($journal)
    {
        $q = $this
            ->createQueryBuilder('cje')
            ->select('MAX(cje.documentNumber)')
            ->leftJoin('cje.cashJournal', 'cj')
            ->where('cj.cashYear = :year')
            ->setParameter('year', $journal->getCashYear())
            ->getQuery();

        return $q->getSingleScalarResult();
    }

    /**
     * @param CashJournal $journal Only entries from this journal are considered
     *
     * @return int|string|null Raw minimum document number, or null when no entries match
     */
    public function getMinDocumentNumber($journal)
    {
        $q = $this
            ->createQueryBuilder('cje')
            ->select('MIN(cje.documentNumber)')
            ->where('cje.cashJournal = :journal')
            ->setParameter('journal', $journal)
            ->getQuery();

        return $q->getSingleScalarResult();
    }

    /**
     * @param string $class Class name; unknown names are not supported
     *
     * @return bool
     */
    public function supportsClass($class)
    {
        return $this->getEntityName() === $class
        || is_subclass_of($class, $this->getEntityName());
    }
}
